# Generated by TinyDesk App Builder.
import tdui

if getattr(tdui, "MAX_CELLS", 2000) < 100:
    raise OSError("Design needs 100 canvas cells; update TinyDesk firmware.")

try:
    import tdapp
except ImportError:
    raise OSError("Update TinyDesk firmware: this app uses the tdapp library.")
if tdapp.VERSION < (1, 0):
    raise OSError("Update TinyDesk firmware for tdapp 1.0.")
canvas_page = tdapp.canvas_page

# --- tdui-editor layout begin ---
win = tdui.Window("Device monitor", 62, 19, x=None, y=None, resizable=True)
heading = win.label(3, 1, "DEVICE MONITOR", width=28)
heading.color(115, -1)
subtitle = win.label(3, 2, "ESP32 / System overview", width=40)
subtitle.color(244, -1)
device_label = win.label(3, 4, "Device name", width=20)
device_name = win.textbox(3, 5, 25, text="workbench-01", secret=False)
auto_refresh = win.checkbox(3, 7, "Auto refresh", checked=True)
load_label = win.label(3, 9, "Memory usage   65%", width=25)
memory = win.progress(3, 10, 25, value=65)
memory.color(78, -1)
refresh = win.button(3, 13, "Refresh")
close_button = win.button(17, 13, "Close")
devices = win.list(33, 4, 25, 5, items=["workbench-01", "sensor-node-02", "display-node-03"])
status = tdapp.make_canvas(win, 33, 11, 25, 4, 1)
footnote = win.label(3, 17, "Ready. Waiting for input.", width=50)
footnote.color(244, -1)

# --- tdui-editor layout end ---

# Canvas painters and page visibility.


def _td_paint_status():
    with tdapp.batch():
        status.fill(0, 0, 25, 4, " ", -1, -1)
        status.fill(0, 0, 25, 4, " ", 115, 234)
        status.put(2, 1, "● SYSTEM ONLINE", 115, 234)
        status.put(2, 2, "All services healthy", 244, 234)

_td_page_names_win = ["Main"]


def _td_show_win(name):
    with tdapp.batch():
        _td_apply_win(name)


def _td_apply_win(name):
    if name not in _td_page_names_win:
        raise ValueError("unknown page")
    heading.visible = name == "Main"
    subtitle.visible = name == "Main"
    device_label.visible = name == "Main"
    device_name.visible = name == "Main"
    auto_refresh.visible = name == "Main"
    load_label.visible = name == "Main"
    memory.visible = name == "Main"
    refresh.visible = name == "Main"
    close_button.visible = name == "Main"
    devices.visible = name == "Main"
    footnote.visible = name == "Main"
    tdapp.show_canvases(win, name)


def show_page(name, window=None):
    if window is None:
        window = win
    if window is win:
        return _td_show_win(name)
    raise ValueError("unknown window")

# Event handlers: keep these quick and nonblocking.


def refresh_device(button):
    memory.value = (memory.value + 5) % 101
    load_label.text = "Memory usage   %d%%" % memory.value
    footnote.text = "Updated successfully."


def close_app(button):
    win.close()

# Wire callbacks after their definitions.
refresh.on_click = refresh_device
close_button.on_click = close_app
tdapp.register_canvas(win, 0, status, status, "Main", 0, 33, 11, _td_paint_status, True, None)
_td_show_win("Main")

tdui.run()

